using EquiApi.Dtos;
using EquiApi.Persistence.Model;

namespace EquiApi.TestInt.Util;

/// <summary>
///     Creates entities and requests with sensible defaults, override only what is relevant for a test.
///     Ids are generated by the database when the entities are seeded.
/// </summary>
internal static class TestData
{
    public const int NonExistingId = 999_999;

    public static Address CreateAddress(string? addressName = null, string plz = "4400", string cityName = "Steyr") =>
        new()
        {
            AddressName = addressName,
            PLZ = plz,
            CityName = cityName
        };

    /// <summary>
    ///     Creates a person with the given role, the roles are seeded by a migration.
    ///     A saddler gets an address with street by default, because saddlers have to provide their street.
    /// </summary>
    public static Person CreatePerson(string firstName = "Max", string lastName = "Mustermann", string? email = null,
                                      Address? address = null, RoleName role = RoleName.Equestrian) => new()
                                      {
                                          FirstName = firstName,
                                          LastName = lastName,
                                          Height = 180M,
                                          Weight = 75M,
                                          DateOfBirth = new LocalDate(1995, 5, 20),
                                          Email = email,
                                          WebsiteLink = role == RoleName.Saddler ? "https://sattler.example.com" : null,
                                          Description = role == RoleName.Saddler ? "Custom saddles" : null,
                                          Address = address ?? CreateAddress(role == RoleName.Saddler
                                                                                 ? "Werkstattgasse 1"
                                                                                 : null),
                                          Roles = [new PersonRoleAssignment { RoleId = GetSeededRoleId(role) }]
                                      };

    public static Horse CreateHorse(string name = "Storm", Address? address = null, params Breed[] breeds) => new()
    {
        Name = name,
        DateOfBirth = new LocalDate(2018, 6, 1),
        Weight = 550M,
        Height = 168M,
        Gender = HorseGender.Male,
        Address = address ?? CreateAddress(),
        HorseBreeds = breeds.Select(breed => new HorseBreed { Breed = breed }).ToList()
    };

    public static Breed CreateBreed(string name = "Haflinger") => new() { Name = name };
    
    public static SaddleCategory CreateSaddleCategory(string name = "Dressage") => new() { Name = name };

    public static Saddle CreateSaddle(Horse horse, string name = "Dressage Saddle",
                                      string categoryName = "Dressage") => new()
                                      {
                                          Name = name,
                                          Horse = horse,
                                          Category = CreateSaddleCategory(categoryName)
                                      };

    public static PersonHorse CreatePersonHorse(Person person, Horse horse, bool isOwner = false,
                                                bool isHidden = false) => new()
                                                {
                                                    Person = person,
                                                    Horse = horse,
                                                    IsOwner = isOwner,
                                                    IsHidden = isHidden
                                                };

    public static PersonRelationship CreateRelationship(Person equestrian, Person saddler, bool isContact = false,
                                                        bool isFavourite = false) => new()
                                                        {
                                                            Equestrian = equestrian,
                                                            Saddler = saddler,
                                                            IsContact = isContact,
                                                            IsFavourite = isFavourite
                                                        };

    public static DeviceCategory CreateDeviceCategory(int numOfAllowedPeople = 5) => new()
    {
        Name = "Standard",
        NumOfAllowedPeople = numOfAllowedPeople
    };

    public static MeasurementDevice CreateDevice(string id, Person owner, DeviceCategory category,
                                                 params Person[] users) => new()
                                                 {
                                                     Id = id,
                                                     Owner = owner,
                                                     Category = category,
                                                     Users = users.Select(user => new DeviceUser { DeviceId = id, User = user }).ToList()
                                                 };

    public static MeasurementGroup CreateMeasurementGroup(Person person, Horse horse, Saddle saddle,
                                                          MeasurementDevice device, string name = "Dressurtraining",
                                                          LocalDate? date = null, string? notes = null) => new()
                                                          {
                                                              Name = name,
                                                              Date = date ?? new LocalDate(2026, 9, 2),
                                                              Notes = notes,
                                                              Person = person,
                                                              Horse = horse,
                                                              Saddle = saddle,
                                                              DeviceId = device.Id,
                                                              Device = device
                                                          };

    /// <summary>
    ///     Creates a measurement with one data entry per given value, a data entry is either a single number or a JSON
    ///     array of numbers. The data entries are one minute apart, starting with the first value.
    /// </summary>
    public static Measurement CreateMeasurement(MeasurementGroup group, string pace = "Schritt", string hand = "Links",
                                                params string[] data) => new()
                                                {
                                                    Group = group,
                                                    Pace = pace,
                                                    Hand = hand,
                                                    MeasurementDates = data.Select((value, index) =>
                                                                                       new MeasurementData
                                                                                       {
                                                                                           Data = value,
                                                                                           Timestamp = Instant.FromUtc(2026, 9, 2, 14, index)
                                                                                       })
                                                                           .ToList()
                                                };

    public static AddMeasurementGroupRequest CreateAddMeasurementGroupRequest(int personId, int horseId, int saddleId,
                                                                              string deviceId,
                                                                              string name = "Galopptraining",
                                                                              LocalDate? date = null) =>
        new(name, date ?? new LocalDate(2025, 12, 30), "Erste Messung", personId, horseId, saddleId, deviceId);

    public static AddMeasurementRequest CreateAddMeasurementRequest(string pace = "Galopp", string hand = "Links",
                                                                    string? description = null) =>
        new(pace, hand, description);

    public static AddressRequest CreateAddressRequest(string? addressName = null, string cityName = "Steyr",
                                                      string plz = "4400") => new(addressName, cityName, plz);

    public static AddPersonRequest CreateAddPersonRequest(string firstName = "Anna", string? email = null,
                                                          RoleName role = RoleName.Equestrian,
                                                          string? websiteLink = null,
                                                          AddressRequest? address = null) =>
        new(firstName, "Reiterin", 170M, 60M, new LocalDate(1998, 3, 15), email, websiteLink, null,
            address ?? CreateAddressRequest(role == RoleName.Saddler ? "Werkstattgasse 1" : null), role);

    public static AddHorseRequest CreateAddHorseRequest(int ownerId, IReadOnlyList<int> breedIds,
                                                        string name = "Neuer", decimal height = 168M,
                                                        LocalDate? dateOfBirth = null) =>
        new(name, dateOfBirth ?? new LocalDate(2018, 6, 1), 550M, height, HorseGender.Female, CreateAddressRequest(),
            breedIds, ownerId);

    private static int GetSeededRoleId(RoleName role) => role switch
    {
        RoleName.Equestrian => 1,
        RoleName.Saddler => 2,
        RoleName.Guest => 3,
        _ => throw new ArgumentOutOfRangeException(nameof(role), role, null)
    };
}